"""V15 search bot — self-contained Kaggle submission.
Generated by package_v15.py. Identical policy to the P2/P3 smoke runs.
Falls back to pure V7 if numba is unavailable.
"""
import base64, os, sys, tempfile, types
import numpy as np

_WEIGHTS_B64 = ""
__v15_weights_path__ = os.path.join(tempfile.gettempdir(), "scorer_v7_kaggle.npz")
try:
    with open(__v15_weights_path__, 'wb') as _f:
        _f.write(base64.b64decode(_WEIGHTS_B64))
except Exception:
    pass

_MODULE_SRC = {
    "bot_v7": "",
    "v15_config": "",
    "v15_fast_sim": "",
    "v15_search": "",
}

def _register(name, inject=None):
    m = types.ModuleType(name)
    m.__dict__['__name__'] = name
    if inject:
        m.__dict__.update(inject)
    src = base64.b64decode(_MODULE_SRC[name]).decode('utf-8')
    sys.modules[name] = m  # register before exec: @dataclass needs it
    exec(compile(src, name + '.py', 'exec'), m.__dict__)
    return m

_register('bot_v7', inject={'__v15_weights_path__': __v15_weights_path__})
_register('v15_config')
_SEARCH_OK = False
try:
    _register('v15_fast_sim')
    _register('v15_search')
    _SEARCH_OK = True
except Exception:
    _SEARCH_OK = False

import bot_v7 as _v7
if _SEARCH_OK:
    import v15_search as _vs

def agent(obs, config=None):
    if _SEARCH_OK:
        try:
            return _vs.search(obs, config, time_budget=0.7,
                              n_rollouts=400, horizon=18)
        except Exception:
            pass
    try:
        return _v7.agent(obs, config)
    except Exception:
        return []
